import { useCallback, useEffect, useState } from "react";
import { extractErrorMessage } from "../api/axios";

/**
 * Wraps any `getAll(params)` API call with pagination, debounced search,
 * and sorting state so list pages don't each reinvent this plumbing.
 *
 * Tries to be forgiving about backend response shape: accepts either
 * { data: [...], total } or a bare array.
 */
export function useApiResource(fetchFn, { pageSize = 10, initialSort = null } = {}) {
  const [rows, setRows] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState("");
  const [sortKey, setSortKey] = useState(initialSort);
  const [sortDir, setSortDir] = useState("asc");
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [refreshTick, setRefreshTick] = useState(0);

  const refetch = useCallback(() => setRefreshTick((t) => t + 1), []);

  const handleSort = useCallback(
    (key) => {
      if (sortKey === key) {
        setSortDir((d) => (d === "asc" ? "desc" : "asc"));
      } else {
        setSortKey(key);
        setSortDir("asc");
      }
    },
    [sortKey]
  );

  useEffect(() => {
    let isCurrent = true;
    setIsLoading(true);
    setError("");

    fetchFn({
      page,
      limit: pageSize,
      search: search || undefined,
      sortBy: sortKey || undefined,
      sortDir: sortKey ? sortDir : undefined
    })
      .then(({ data }) => {
        if (!isCurrent) return;
        const list = Array.isArray(data) ? data : data?.data || data?.items || [];
        const totalCount = Array.isArray(data)
          ? data.length
          : data?.total ?? data?.count ?? list.length;
        setRows(list);
        setTotal(totalCount);
      })
      .catch((err) => {
        if (!isCurrent) return;
        setError(extractErrorMessage(err, "Unable to load records."));
        setRows([]);
        setTotal(0);
      })
      .finally(() => {
        if (isCurrent) setIsLoading(false);
      });

    return () => {
      isCurrent = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, search, sortKey, sortDir, refreshTick]);

  // Reset to page 1 whenever the search term changes.
  useEffect(() => {
    setPage(1);
  }, [search]);

  return {
    rows,
    total,
    page,
    setPage,
    pageSize,
    search,
    setSearch,
    sortKey,
    sortDir,
    handleSort,
    isLoading,
    error,
    refetch
  };
}
